using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
[InitializeOnLoad]public static class TrainingFrontChecks {
 const string Pending="ShiokaFrontChecks";static string report,folder;static List<string> rows;static int count,stage,frame;static double deadline;static Keyboard keyboard;static InputSettings old,temporary;static IDisposable keyProfile;static PlayerPreferencesStore store;static string saved;static TrainingFrontMenu menu;static string sceneBytes,profileBytes;static bool injected;
 static TrainingFrontChecks(){if(SessionState.GetBool(Pending,false))EditorApplication.update+=Tick;}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Fresh Edit session required");EditorSceneManager.OpenScene(TrainingFlowSession.TitleScene);SessionState.SetBool(Pending,true);EditorApplication.update-=Tick;EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Check(bool value,string text){rows.Add((value?"PASS ":"FAIL ")+text);if(!value)throw new Exception(text);count++;}
 static void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));InputSystem.Update();}
 static void Next(int value){stage=value;frame=Time.frameCount;}
 static void SceneLoaded(Scene scene,LoadSceneMode mode){if(scene.path==TrainingFlowSession.TitleScene){var front=UnityEngine.Object.FindAnyObjectByType<TrainingFrontMenu>();front.UseStoreForTests(store);injected=true;}}
 static TrainingFrontMenu Front()=>UnityEngine.Object.FindAnyObjectByType<TrainingFrontMenu>();
 static void Setup(){rows=new List<string>();var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-frontReport");report=i<0?"Temp/front-checks.txt":args[i+1];folder=Path.Combine(Path.GetTempPath(),"Shioka-front-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);store=new PlayerPreferencesStore(Path.Combine(folder,"preferences.json"));int reload=Array.IndexOf(args,"-frontSavedPreferencesFile");if(reload>=0)File.Copy(args[reload+1],store.Path);keyProfile=KeyConfigService.UseForTests(KeyConfigService.Defaults(),new KeyConfigStore(Path.Combine(folder,"keys.json")));old=InputSystem.settings;temporary=UnityEngine.Object.Instantiate(old);temporary.updateMode=InputSettings.UpdateMode.ProcessEventsManually;temporary.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temporary.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temporary;keyboard=InputSystem.AddDevice<Keyboard>();Application.runInBackground=true;SceneManager.sceneLoaded+=SceneLoaded;menu=Front();menu.UseStoreForTests(store);sceneBytes=File.ReadAllText(TrainingFlowSession.TrainingScene);profileBytes=File.ReadAllText("Assets/Shioka/調整Data/Fighter/Awari/Move/ApprovedLocomotionProfile.asset");deadline=EditorApplication.timeSinceStartup+120;Check(menu!=null&&!menu.FighterSelectionVisible,"actual Title scene boot");if(reload>=0){Check(menu.SelectedId=="awari","fresh Unity process restores saved character in actual UI");Check(File.ReadAllText(store.Path)==File.ReadAllText(args[reload+1]),"restart load preserves saved bytes");Finish(0);return;}Check(!File.Exists(store.Path),"opening Title does not create preferences");Check(menu.SelectedId=="awari","missing file resolves actual catalog default");Check(EditorBuildSettings.scenes[0].path==TrainingFlowSession.TitleScene&&EditorBuildSettings.scenes.Any(s=>s.path==TrainingFlowSession.TrainingScene&&s.enabled),"Title first and Training direct entry both retained");Keys();Next(0);}
 static void Capture(string name){var camera=menu.MenuCamera;var previous=camera.targetTexture;var active=RenderTexture.active;var target=new RenderTexture(1280,720,24);target.Create();try{camera.targetTexture=target;Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Path.ChangeExtension(report,null)+"-"+name+".png",image.EncodeToPNG());UnityEngine.Object.Destroy(image);}finally{camera.targetTexture=previous;RenderTexture.active=active;target.Release();UnityEngine.Object.Destroy(target);}}
 static void Tick(){try{if(!EditorApplication.isPlaying||Time.frameCount<3)return;if(rows==null){Setup();return;}InputSystem.Update();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Front flow timeout stage "+stage);if(Time.frameCount-frame<4)return;
 switch(stage){case 0:Capture("title");Keys(Key.J);Next(1);break;
 case 1:Check(menu.FighterSelectionVisible,"virtual confirm enters fighter selection");Check(!File.Exists(store.Path),"opening selection does not save");Capture("fighters");Keys();Next(2);break;
 case 2:Keys(Key.K);Next(3);break;
 case 3:Check(!menu.FighterSelectionVisible,"virtual cancel returns to Title");Check(!File.Exists(store.Path),"cancel keeps disk unchanged");Keys();var invalid=new PlayerPreferences{selectedFighterId="missing-fighter"};Check(store.Save(invalid,out _),"fixture unavailable ID saved in isolated store");saved=File.ReadAllText(store.Path);menu.UseStoreForTests(store);Check(menu.SelectedId=="awari"&&File.ReadAllText(store.Path)==saved,"unavailable ID fallback is non-destructive");File.WriteAllText(store.Path,"broken-json");menu.UseStoreForTests(store);Check(menu.SelectedId=="awari"&&File.ReadAllText(store.Path)=="broken-json","corrupt preferences fallback preserves original");menu.UseStoreForTests(new PlayerPreferencesStore(folder));menu.OpenFighterSelect();menu.StartTraining();Check(!menu.Starting&&SceneManager.GetActiveScene().path==TrainingFlowSession.TitleScene,"save failure refuses scene transition");menu.UseStoreForTests(store);menu.OpenFighterSelect();menu.SelectFighter("not-connected");Check(menu.SelectedId=="awari","unknown fighter cannot be selected");menu.SelectFighter("awari");Check(menu.GetComponentsInChildren<Button>().Count(b=>b.name.Contains("ぁゎり"))==1,"only current connected fighter offered");Keys();Next(4);break;
 case 4:Keys(Key.S);Next(5);break;
 case 5:Keys();Next(6);break;
 case 6:Keys(Key.J);Next(7);break;
 case 7:if(SceneManager.GetActiveScene().path!=TrainingFlowSession.TrainingScene)break;var hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();if(hud==null||hud.player==null||hud.MatchDisplay==null)break;Check(!TrainingFlowSession.AwaitingTrainingEntry,"training consumes entry neutral gate");Check(hud.player.GetComponent<ApprovedLocomotionTuning>()!=null&&hud.player.opponent.GetComponent<ApprovedLocomotionTuning>()!=null&&hud.player.GetComponent<ApprovedLocomotionTuning>().canonicalProfile==hud.player.opponent.GetComponent<ApprovedLocomotionTuning>().canonicalProfile,"shared canonical locomotion retained through scene entry");Check(!hud.player.InputBuffer.History.Any(h=>h.Command==TrainingCommand.Light),"held menu confirm never becomes training LP");Check(File.ReadAllText(TrainingFlowSession.TrainingScene)==sceneBytes&&File.ReadAllText("Assets/Shioka/調整Data/Fighter/Awari/Move/ApprovedLocomotionProfile.asset")==profileBytes,"scene and movement authoring bytes unchanged by flow");Check(store.Load("none",out _).selectedFighterId=="awari","explicit Start persists stable selected ID");Check(new PlayerPreferencesStore(store.Path).Load("none",out _).selectedFighterId=="awari","cold store reload preserves selected fighter");Keys();Next(8);break;
 case 8:Keys(Key.D);Next(9);break;
 case 9:var playing=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();Check(playing.player.HorizontalVelocity>0,"fresh gameplay movement accepted after neutral release");Keys();playing.SetOptionVisible(true);playing.ShowInputOptions(true);var back=playing.GetComponentsInChildren<Button>(true).FirstOrDefault(b=>b.name=="NavTitle");if(back==null)back=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(b=>b.name=="NavTitle");Check(back.gameObject.activeInHierarchy&&back.interactable,"common return button visible from KeyConfig");back.onClick.Invoke();Next(10);break;
 case 10:if(SceneManager.GetActiveScene().path!=TrainingFlowSession.TitleScene||Front()==null)break;menu=Front();Check(injected,"return Title receives isolated test persistence before Start");Check(!menu.FighterSelectionVisible&&menu.SelectedId=="awari","return from Training restores Title and saved character");Check(Time.timeScale==1,"return restores normal time scale");Check(UnityEngine.Object.FindAnyObjectByType<TrainingFighter>()==null,"Training actors removed on return");menu.OpenFighterSelect();Check(menu.SelectedId=="awari","reopening selection uses saved character");menu.Back();Check(!menu.FighterSelectionVisible,"mouse action Back shares same return path");Finish(0);break;}
 }catch(Exception e){rows?.Add("EXCEPTION "+e);Debug.LogException(e);Finish(1);}}
 static void Finish(int exit){SessionState.SetBool(Pending,false);EditorApplication.update-=Tick;SceneManager.sceneLoaded-=SceneLoaded;Keys();keyProfile?.Dispose();if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(old!=null)InputSystem.settings=old;if(temporary!=null)UnityEngine.Object.DestroyImmediate(temporary);Time.timeScale=1;if(rows!=null){rows.Add(count+" PASS; exit="+exit+"; virtual keyboard and Button.onClick, not physical devices/mouse");rows.Add("Isolated recovery "+folder);File.WriteAllLines(report,rows);}EditorApplication.Exit(exit);}
}
